import subprocess, os, pty, select, struct, fcntl, termios, time
def run_tty(args, stdin_data=b"X"*64, cols=80):
    master, slave = pty.openpty()
    winsize = struct.pack("HHHH", 24, cols, 0, 0)
    fcntl.ioctl(slave, termios.TIOCSWINSZ, winsize)
    proc = subprocess.Popen(["./executable"]+args, stdin=subprocess.PIPE, stdout=slave, stderr=slave, close_fds=True)
    os.close(slave)
    try:
        proc.stdin.write(stdin_data)
        proc.stdin.close()
    except Exception as e:
        print("write err",e)
    out=b""
    # read until proc exits
    while True:
        rlist,_,_ = select.select([master], [], [], 1.0)
        if rlist:
            try:
                chunk=os.read(master, 8192)
                if not chunk:
                    break
                out+=chunk
            except OSError as e:
                break
        else:
            if proc.poll() is not None:
                # try drain
                try:
                    import fcntl as f
                    flags = f.fcntl(master, f.F_GETFL)
                    f.fcntl(master, f.F_SETFL, flags | os.O_NONBLOCK)
                    while True:
                        try:
                            chunk=os.read(master, 8192)
                            if not chunk: break
                            out+=chunk
                        except BlockingIOError:
                            break
                        except OSError:
                            break
                except: pass
                break
    proc.wait(timeout=5)
    os.close(master)
    return out, proc.returncode

for cols in [40,80,120,200]:
    out,code = run_tty(["--color=never"], cols=cols)
    txt=out.decode(errors='replace')
    txt2=txt.replace("\r\n","\n").replace("\r","")
    print(f"=== COLS={cols} code={code} rawlen={len(out)} ===")
    print(repr(txt2[:2000]))
    print()
