def run_tty(args, stdin_data=b"hello", cols=80, env=None):
    import os
    master, slave = pty.openpty()
    winsize = struct.pack("HHHH", 24, cols, 0, 0)
    fcntl.ioctl(slave, termios.TIOCSWINSZ, winsize)
    e=os.environ.copy()
    if env:
        for k,v in env.items():
            e[k]=v
    else:
        e.pop("NO_COLOR", None)
    proc = subprocess.Popen(["./executable"]+args, stdin=subprocess.PIPE, stdout=slave, stderr=slave, env=e, close_fds=True)
    os.close(slave)
    try:
        proc.stdin.write(stdin_data)
        proc.stdin.close()
    except: pass
    out=b""
    while True:
        rlist,_,_ = select.select([master], [], [], 1.0)
        if rlist:
            try:
                chunk=os.read(master, 8192)
                if not chunk: break
                out+=chunk
            except OSError: break
        else:
            if proc.poll() is not None:
                try:
                    import fcntl as f
                    flags = f.fcntl(master, f.F_GETFL)
                    f.fcntl(master, f.F_SETFL, flags | os.O_NONBLOCK)
                    while True:
                        try:
                            chunk=os.read(master, 8192)
                            if not chunk: break
                            out+=chunk
                        except: break
                except: pass
                break
    proc.wait(timeout=5)
    os.close(master)
