    return iv
def parse_base5(s):
    if s in ('hexadecimal','hex','x'): return 'x'
    if s in ('binary','bin','b'): return 'b'
    if s in ('octal','oct','o'): return 'o'
    if s in ('decimal','dec','d'): return 'd'
