            else: cparts.append(" "*8)
        s+=b_char.join(cparts)
        s+=b_out
    else:
        s+=b_out
    return s

def build_end_line2(end_off, panels, show_pos, show_chars, border, base, group, color_en, cmap):
    if border=='unicode': b_out="│";b_hex="┊";b_char="┊";b_mid="│"
