            if g in ('characters','no-characters'): last=g
        if last is None: show_chars=True
        else: show_chars=(last=='characters')
        show_pos=('no-position' not in vals)
        border_opt=vals.get('border','unicode')
        color_when=vals.get('color','always')
    char_name=vals.get('character-table','default')
    scheme=vals.get('color-scheme','default')
    last_e=None;last_e_val=None
    for g,v in order:
        if g=='e-flag': last_e='e-flag'
        elif g=='endianness': last_e='endianness';last_e_val=v
    if last_e is None: endian='big'
    elif last_e=='e-flag': endian='little'
    else: endian=last_e_val
    little=(endian=='little')
    no_squeeze=('no-squeezing' in vals)
    is_inc=('include' in vals)
    color_en=should_color2(color_when)
    panels_c=comp_panels(show_pos,show_chars,base_opt,group_opt,popt,topt)
    tbl=get_char_tbl(char_name)
    cmap=get_def_colors()
    use_grad=(scheme=='gradient')
    grad_tbl=GRADIENT_TABLE
    # read
    data=b'';skip_off=0
    if file_arg is not None:
        try: f=open(file_arg,'rb')
        except FileNotFoundError: eprint('Error: No such file or directory (os error 2)\n');sys.exit(1)
        except IsADirectoryError: eprint('Error: Is a directory (os error 21)\n');sys.exit(1)
        except OSError as e:
            try: msg=e.strerror;no=e.errno
            except: msg=str(e);no=1
            eprint(f'Error: {msg} (os error {no})\n');sys.exit(1)
