                f.seek(pos,0);skip_off=pos
            else:
                if skip>0:
                    try: f.seek(skip,0)
                    except: f.seek(0,2)
                    skip_off=skip
                else: skip_off=0
            if length is not None:
                data=f.read(length) if length!=0 else b''
            else: data=f.read()
            f.close()
        except OSError as e:
            try: msg=e.strerror;no=e.errno
            except: msg=str(e);no=1
            eprint(f'Error: {msg} (os error {no})\n');sys.exit(1)
    else:
        inp=sys.stdin.buffer.read()
        if isinstance(skip,int) and skip<0:
            eprint('Error: Failed to jump to the desired input position. This could be caused by a negative offset that is too large or by an input that is not seek-able (e.g. if the input comes from a pipe).\n');sys.exit(1)
        if skip>0:
            data=inp[skip:] if skip<len(inp) else b''
            skip_off=skip
        else:
            data=inp;skip_off=0
        if length is not None: data=data[:length]
    if is_inc:
        do_include_main(data)
        sys.exit(0)
    # normal
    out=sys.stdout.buffer
    row_size=panels_c*8
    rows=[data[i:i+row_size] for i in range(0,len(data),row_size)] if len(data)>0 else []
    if len(rows)==0:
        if border_opt!='none':
            hdr=build_header_str(border_opt,show_pos,show_chars,panels_c,base_opt,group_opt)
            ftr=build_footer_str(border_opt,show_pos,show_chars,panels_c,base_opt,group_opt)
            out.write((hdr+"\n").encode())
        mid_hw=hpw('x',group_opt)
        parts=["\u2502"]
        if show_pos: parts.append(" "*8);parts.append("\u2502")
        nc=" No content"
        parts.append(nc+" "*(mid_hw-len(nc)));parts.append("\u2502")
        parts.append(" "*mid_hw);parts.append("\u2502")
        if show_chars:
            parts.append(" "*8);parts.append("\u2502")
            parts.append(" "*8);parts.append("\u2502")
        out.write(("".join(parts)+"\n").encode())
        if border_opt!='none':
            out.write((ftr+"\n").encode())
        sys.exit(0)
    if border_opt!='none':
        hdr=build_header_str(border_opt,show_pos,show_chars,panels_c,base_opt,group_opt)
        ftr=build_footer_str(border_opt,show_pos,show_chars,panels_c,base_opt,group_opt)
        out.write((hdr+"\n").encode())
    def is_unif(r):
        if len(r)!=row_size: return False
        f=r[0]
        for b in r:
            if b!=f: return False
        return True
    prev=None;sq_act=False;sq_once=False
    for idx,row in enumerate(rows):
        cur_off=skip_off+disp+idx*row_size
        if (not no_squeeze) and len(row)==row_size and is_unif(row) and prev is not None and len(prev)==row_size and is_unif(prev) and row==prev:
            if not sq_act:
                line=build_squeeze_line(show_pos,show_chars,panels_c,border_opt,base_opt,group_opt,color_en,cmap)
                out.write((line+"\n").encode('utf-8'))
            sq_act=True;sq_once=True;prev=row
            continue
        else:
            sq_act=False
            line=build_data_line(row,cur_off,panels_c,show_pos,show_chars,border_opt,base_opt,group_opt,little,color_en,cmap,grad_tbl,use_grad,tbl)
            out.write((line+"\n").encode('utf-8'))
            prev=row
            continue
    if (not no_squeeze) and sq_once and len(data)%row_size==0:
        end_off=skip_off+disp+len(data)
        line=build_end_line(end_off,panels_c,show_pos,show_chars,border_opt,base_opt,group_opt,color_en,cmap)
        out.write((line+"\n").encode('utf-8'))
    if border_opt!='none':
        out.write((ftr+"\n").encode())

if __name__=='__main__':
    main_inner()
